async function saveAppointment(id) { const appointment = appointmentById(id); const modal = document.getElementById('modal'); const status = modal.dataset.pendingStatus || appointment.status; const note = modal.querySelector('#staffNote').value.trim(); const paidInput = modal.querySelector('#amountPaid'); const dueInput = modal.querySelector('#amountDue'); const amountPaid = paidInput?.value.trim(); const outcomeReason = modal.querySelector('#outcomeReason')?.value || ''; if (['cancelled','no_show'].includes(status) && !outcomeReason) return showToast('اختاري سبب الإلغاء أو عدم الحضور أولًا.'); const update = { status, staff_note:note, requested_time:modal.querySelector('#requestedTime')?.value || null, is_waitlist:Boolean(modal.querySelector('#waitlist')?.checked), outcome_reason:['cancelled','no_show'].includes(status) ? outcomeReason : '', outcome_note:['cancelled','no_show'].includes(status) ? (modal.querySelector('#outcomeNote')?.value.trim() || '') : '' }; if (amountPaid !== '' && status !== 'completed') return showToast('اختاري «تمت الزيارة» قبل تسجيل وسيلة الدفع.'); if (amountPaid !== '') { const paid = Number(amountPaid); const due = Number(dueInput?.value || 0); if (!Number.isFinite(paid) || paid < 0 || !Number.isFinite(due) || due < 0) return showToast('راجعي المبالغ المدخلة.'); Object.assign(update,{ amount_due:due, amount_paid:paid, payment_method:modal.querySelector('#paymentMethod')?.value || 'cash', payment_note:modal.querySelector('#paymentNote')?.value.trim() || '', payment_recorded_by:session.user.id, payment_recorded_at:new Date().toISOString() }); } const { error } = await supabase.from('appointments').update(update).eq('id', id); if (error) return showToast('تعذر حفظ التحديث. تأكدي من تشغيل ترقية قاعدة البيانات أولًا.'); const paymentNote = amountPaid !== '' ? ` تم تسجيل دفع ${money(amountPaid)} عبر ${paymentMethodText(update.payment_method)}.${update.payment_note ? ` ملاحظة: ${update.payment_note}` : ''}` : ''; const outcomeText = update.outcome_reason ? ` السبب: ${outcomeReasonText(update.outcome_reason)}.` : ''; const eventNote = (note || `تم تغيير الحالة إلى ${statusLabels[status]}.`) + outcomeText + paymentNote; const { error: eventError } = await supabase.from('appointment_events').insert({ appointment_id:id, actor_id:session.user.id, event_type:'updated', old_status:appointment.status, new_status:status, note:eventNote }); if (eventError) return showToast('تم حفظ الحالة، لكن تعذر حفظ ملاحظة السجل.'); const waitlisted = status === 'cancelled' ? appointments.filter(item => item.is_waitlist && item.requested_date === appointment.requested_date && activeBooking(item)).length : 0; await loadData(); modal.remove(); renderApp(); showToast(waitlisted ? `تم الحفظ. يوجد ${waitlisted} في قائمة انتظار هذا اليوم؛ افتحي قائمة الانتظار لتحديد الموعد.` : 'تم حفظ تحديث الطلب بنجاح.'); }
